"""
Pydantic v2 API Schemas
Owner: Shivam (Backend & APIs)

Defines unified request and response contracts for /health, /api/upload,
/api/analyze, and /api/report/{report_id}.
"""

from datetime import datetime, timezone
from typing import List, Optional, Dict, Any, Literal
from pydantic import BaseModel, Field

from ai.common.schemas import (
    LabelPrediction,
    EvidenceCitation,
    AgentStageTrace,
)

DEMO_MODE_DISCLAIMER = (
    "DEMO MODE: Results are simulated and are not generated by a trained medical model. "
    "This research prototype is NOT a clinical diagnostic system."
)

REAL_MODE_DISCLAIMER = (
    "RESEARCH PROTOTYPE: Output is generated for academic research evaluation only and "
    "must not be used for clinical diagnosis."
)


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


class HealthCheckResponse(BaseModel):
    status: str = Field(..., description="Overall service status ('healthy' or 'degraded')")
    service: str = Field(default="radiology-backend")
    database_status: str = Field(default="connected (sqlite)")
    ai_mode: Literal["mock", "real"] = Field(default="mock")
    modality_scope: str = Field(default="Chest X-Ray (DX)")
    integrations: Dict[str, Any] = Field(default_factory=dict)
    timestamp: datetime = Field(default_factory=_utc_now)


class ScanUploadResponse(BaseModel):
    scan_id: str = Field(..., description="UUID of the persisted scan record")
    filename: str = Field(..., description="Sanitized original filename")
    media_type: str = Field(..., description="Verified MIME media type, e.g., image/png")
    status: str = Field(default="uploaded", description="Processing state of the scan")
    # Backward-compatible fields
    file_type: str = Field(..., description="Alias for media_type")
    file_size_bytes: int = Field(default=0)
    image_metadata: Optional[Dict[str, Any]] = Field(default=None)
    message: str = Field(default="Scan validated and stored successfully.")


class AnalysisRequest(BaseModel):
    scan_id: str = Field(..., min_length=1, description="UUID of a previously uploaded scan")
    notes: Optional[str] = Field(default=None, description="Optional clinical context notes")


class ReportResponse(BaseModel):
    """Unified structured response returned by POST /api/analyze and GET /api/report/{report_id}."""

    report_id: str = Field(..., description="UUID of the persisted radiology report")
    id: str = Field(..., description="Alias for report_id for backward compatibility")
    scan_id: str = Field(..., description="UUID of the analyzed scan")
    status: str = Field(default="completed", description="Analysis execution status")
    mode: Literal["mock", "real"] = Field(..., description="Execution mode ('mock' or 'real')")
    disclaimer: str = Field(default=DEMO_MODE_DISCLAIMER)
    model_name: str = Field(..., description="Vision classification model identifier")
    predictions: List[LabelPrediction] = Field(
        default_factory=list,
        description="Multi-label Chest X-Ray abnormality scores (uncalibrated model outputs)",
    )
    heatmap_available: bool = Field(
        default=False,
        description="Whether a genuine Grad-CAM heatmap is available",
    )
    heatmap_url: Optional[str] = Field(
        default=None,
        description="URL to Grad-CAM heatmap if available, otherwise null",
    )
    explainability_message: str = Field(
        default="Grad-CAM heatmap is unavailable in mock mode."
    )
    findings: List[str] = Field(default_factory=list, description="Structured findings list")
    impression: str = Field(..., description="Synthesized radiology report impression")
    evidence_status: str = Field(
        default="sufficient",
        description="Verification status of retrieved literature ('sufficient', 'insufficient', 'unverified_claims')",
    )
    evidence: List[EvidenceCitation] = Field(
        default_factory=list,
        description="Retrieved and reranked medical literature citations",
    )
    agent_trace: List[AgentStageTrace] = Field(
        default_factory=list,
        description="Step-by-step execution trace across vision and RAG pipeline stages",
    )
    image_metadata: Optional[Dict[str, Any]] = Field(
        default=None,
        description="Extracted Chest X-Ray image dimensions and intensity statistics",
    )
    confidence: float = Field(
        default=0.0,
        description="Top abnormality score (retained for backward compatibility; not clinical confidence)",
    )
    created_at: datetime = Field(default_factory=_utc_now)


# Alias so both AnalysisResponse and ReportResponse share the exact same contract
AnalysisResponse = ReportResponse
